1	package com.acme.report;
2	
3	import java.io.IOException;
4	import java.nio.charset.StandardCharsets;
5	import java.nio.file.Files;
6	import java.nio.file.Path;
7	import java.nio.file.Paths;
8	
9	import org.apache.logging.log4j.LogManager;
10	import org.apache.logging.log4j.Logger;
11	
12	/**
13	 * report-svc — the nightly report generator for the analytics platform.
14	 *
15	 * It reads the pending report request (an external, caller-supplied value) and
16	 * writes an audit log line for it so downstream reconciliation can replay what
17	 * was generated. The request text is logged verbatim, which is why the logging
18	 * implementation on the runtime classpath matters.
19	 */
20	public final class ReportApp {
21	
22	    private static final Logger LOG = LogManager.getLogger(ReportApp.class);
23	
24	    private ReportApp() {
25	    }
26	
27	    /** Read the caller-supplied report request, or fall back to a default. */
28	    private static String readRequest() {
29	        Path req = Paths.get("data", "request.txt");
30	        try {
31	            if (Files.exists(req)) {
32	                String text = new String(Files.readAllBytes(req), StandardCharsets.UTF_8).trim();
33	                if (!text.isEmpty()) {
34	                    return text;
35	                }
36	            }
37	        } catch (IOException e) {
38	            // fall through to the default request title
39	        }
40	        return "Monthly Revenue Summary";
41	    }
42	
43	    public static void main(String[] args) {
44	        String request = readRequest();
45	        // External input flows into the audit log message.
46	        LOG.info("Generated report: {}", request);
47	        System.out.println("report-svc: report generated for request '" + request + "'");
48	    }
49	}
